use std :: path :: PathBuf ; # [doc = " Operations that can be performed and need policy checking"] # [derive (Debug , Clone , PartialEq , Eq)] pub enum PermissionOperation { # [doc = " Write operation to a file path"] Write { path : PathBuf , cwd : PathBuf , message : String , } , # [doc = " Read operation from a file path"] Read { path : PathBuf , cwd : PathBuf , message : String , } , # [doc = " Execute operation with a command string"] Execute { command : String , cwd : PathBuf } , # [doc = " Network fetch operation with a URL"] Fetch { url : String , cwd : PathBuf , message : String , } , }